-- FIXTURE — replaceable business data, dev/staging ONLY. Never applied to prod.
--
-- Reserved fixture UUID prefix 'f1f7' (see courts.sql / packages/db/README.md).
-- Suffix namespaces used here (last 12 hex chars):
--   ingredients                000000001001..1048 (purchased), 1051..1052 (prepared)
--   recipe_lines (variant)     0b00000<item2><v><line2>   e.g. 0b0000002101
--   recipe_lines (modifier)    0b00000d<g>0<line2>        e.g. 0b00000d1001
--   recipe_lines (sub-recipe)  0b00000c<r>0<line2>        e.g. 0b00000c1001
--   deliveries                 00000000de01..de03
--   delivery_lines             0000000e1<ddd>             e.g. 0000000e1101
--   stock_batches              0000000ba<ddd> (mirrors its delivery line),
--                              0000000ba9<dd> (synthetic batches of prepared)
--
-- Depends on fixtures/menu.sql (variant + modifier ids). Expiry dates are all
-- RELATIVE to current_date so fixtures never go stale. Opening stock arrives as
-- plain INSERTs (deliveries -> delivery_lines -> stock_batches) plus matching
-- goods_in / production_in ledger rows (guarded WHERE NOT EXISTS: stock_movements
-- has identity ids and is append-only, so re-running never duplicates).

begin;

