ins_lines as (
  insert into delivery_lines (id, delivery_id, ingredient_id, qty_expected, qty_received, unit_cost_iqd, expiry_date)
  select line_id::uuid, delivery_id::uuid, ingredient_id::uuid, qty_expected, qty_received, unit_cost_iqd, expiry_date
    from lines
  on conflict (id) do nothing
)
insert into stock_batches (id, ingredient_id, delivery_line_id, received_at, expiry_date, qty_received, qty_remaining, unit_cost_iqd)
select replace(line_id, '0000000e1', '0000000ba')::uuid,
       ingredient_id::uuid, line_id::uuid, received_at, expiry_date,
       qty_received, qty_received, unit_cost_iqd
  from lines
on conflict (id) do nothing;

