on conflict (id) do nothing;

-- ---------------------------------------------------------------------------
-- Matching ledger rows — stock_movements has identity ids and is append-only,
-- so idempotency comes from WHERE NOT EXISTS instead of fixture ids.
-- ---------------------------------------------------------------------------
insert into stock_movements (at, ingredient_id, batch_id, movement_type, qty_delta,
                             unit_cost_iqd, delivery_line_id, staff_id)
select b.received_at, b.ingredient_id, b.id, 'goods_in', b.qty_received,
       b.unit_cost_iqd, b.delivery_line_id, 'a0000000-0000-4000-8000-000000000002'
  from stock_batches b
 where b.id::text like 'f1f70000-%'
   and b.delivery_line_id is not null
   and not exists (select 1 from stock_movements m
                    where m.batch_id = b.id and m.movement_type = 'goods_in');

insert into stock_movements (at, ingredient_id, batch_id, movement_type, qty_delta,
                             unit_cost_iqd, staff_id)
select b.received_at, b.ingredient_id, b.id, 'production_in', b.qty_received,
       b.unit_cost_iqd, 'a0000000-0000-4000-8000-000000000002'
  from stock_batches b
 where b.id in ('f1f70000-0000-4000-8000-0000000ba901',
                'f1f70000-0000-4000-8000-0000000ba902')
   and not exists (select 1 from stock_movements m
                    where m.batch_id = b.id and m.movement_type = 'production_in');

commit;
